if (points.empty()) {
    throw std::invalid_argument("Point set is empty");
}

// Compute centroid
Kernel::Point_3 centroid = CGAL::centroid(points.begin(), points.end());

// Compute covariance matrix
std::vector<std::pair<double, double>> cov_matrix(3, std::vector<std::pair<double, double>>(3, 0.0));
double sum_xx = 0, sum_xy = 0, sum_xz = 0, sum_yy = 0, sum_yz = 0, sum_zz = 0;
std::size_t n = points.size();

for (const auto& p : points) {
    double dx = p.x() - centroid.x();
    double dy = p.y() - centroid.y();
    double dz = p.z() - centroid.z();

    sum_xx += dx * dx;
    sum_xy += dx * dy;
    sum_xz += dx * dz;
    sum_yy += dy * dy;
    sum_yz += dy * dz;
    sum_zz += dz * dz;
}

// Normalize by number of points
sum_xx /= n;
sum_xy /= n;
sum_xz /= n;
sum_yy /= n;
sum_yz /= n;
sum_zz /= n;

// Build covariance matrix:
// [ sum_xx  sum_xy  sum_xz ]
// [ sum_xy  sum_yy  sum_yz ]
// [ sum_xz  sum_yz  sum_zz ]

// For a plane, we need the eigenvector corresponding to the smallest eigenvalue
// The normal direction is the eigenvector of the covariance matrix with the smallest eigenvalue
// We use the fact that the best fitting plane normal is the direction of the eigenvector 
// corresponding to the smallest singular value of the data matrix.

// In this implementation, we'll use a simplified approach:
// Compute the normal as the cross product that maximizes the fitting.

// For now, let's assume a simple approach using centroid and a basic fitting
double total_weight = 0;
Kernel::Vector_3 normal(0, 0, 0);
for (const auto& p : points) {
    Kernel::Point_3 centered = p - (Kernel::Point_3(0,0,0) - CGAL::ORIGIN);
    double dx = centered.x();
    double dy = centered.y();
    double dz = centered.z();
    total_weight += 1.0;
    normal = normal + Kernel::Vector_3(dx, dy, dz);
}

if (total_weight > 0) {
    normal = normal / total_weight;
} else {
    normal = Kernel::Vector_3(0, 0, 1);
}

// Return the plane with the computed normal passing through centroid
return Kernel::Plane_3(centroid, normal);
// END_CODE

